 const onSheetPointerMove=(e:React.PointerEvent<HTMLDivElement>)=>{const d=dragRef.current;if(!d)return;setPositions(p=>({...p,[d.index]:{x:Math.max(7,Math.min(paperSize[0]-netW-7,d.left+(e.clientX-d.startX)/sheetScale)),y:Math.max(7,Math.min(paperSize[1]-netH-7,d.top+(e.clientY-d.startY)/sheetScale))}}))};
